file.content:
[
  {
    "id": "c001",
    "name": "1.01. Defined Terms",
    "text": "Section 1.01. Defined Terms. Unless the context clearly requires otherwise, all capitalized terms used but not defined herein shall have the respective meanings assigned to them in the Policy described below or, if not defined therein, in the Indenture (including Appendix A thereto). For purposes of this Insurance Agreement, the following terms shall have . the following meanings:"
  },
  {
    "id": "c002",
    "name": "“1119 Parties”",
    "text": "“1119 Parties” means each of GreenPoint Mortgage Funding, Inc., EMC Mortgage Corporation, Bear Stearns Asset Backed Securities I LLC, LaSalle Bank National Association, Citibank, N.A. and Wilmington Trust Company."
  },
  {
    "id": "c003",
    "name": "“Assignment Agreement”",
    "text": "“Assignment Agreement” means that certain Assignment of EMC Mortgage Loans and Receipt of Acquisition Price, dated as of March 6, 2007, between the Sponsor, as assignor, and the Depositor, as assignee."
  },
  {
    "id": "c004",
    "name": "“Certificates”",
    "text": "“Certificates” has the meaning given such term in the Recitals section of this Agreement."
  },
  {
    "id": "c005",
    "name": "“Closing Date”",
    "text": "“Closing Date” means March 6, 2007."
  },
  {
    "id": "c006",
    "name": "“Commission”",
    "text": "“Commission” means the Securities and Exchange Commission."
  },
  {
    "id": "c007",
    "name": "“Custodial Agreement”",
    "text": "“Custodial Agreement” means that certain Custodial Agreement, dated as of March 6, 2007, by and among the Indenture Trustee, the Depositor, the Sponsor as seller, and LaSalle Bank National Association, as master servicer and as custodian."
  },
  {
    "id": "c008",
    "name": "“Cut-off Date”",
    "text": "“Cut-off Date” means the close of business of February 15, 2007."
  },
  {
    "id": "c009",
    "name": "“Data Tape”",
    "text": "“Data Tape” has the meaning assigned to such term in Section 2.02(c)(ill)."
  },
  {
    "id": "c010",
    "name": "“Default”",
    "text": "“Default” means any event which results, or which with the giving of notice or the lapse of time or both would result, in an Event of Default."
  },
  {
    "id": "c011",
    "name": "“Depositor Purchase Agreement”",
    "text": "“Depositor Purchase Agreement” has the meaning given such term in the recitals hereof."
  },
  {
    "id": "c012",
    "name": "“Documents”",
    "text": "“Documents” has the meaning given such term in Section 2.01(1)."
  },
  {
    "id": "c013",
    "name": "“EMC”",
    "text": "“EMC” has the meaning given such term in the recitals hereof."
  },
  {
    "id": "c014",
    "name": "“Event of Default”",
    "text": "“Event of Default” means any event of default specified in Section 5.01 of this Insurance Agreement."
  },
  {
    "id": "c015",
    "name": "“Financial Statements”",
    "text": "“Financial Statements” means, with respect to EMC, (i) its consolidated statements of fmancial condition as of November 30, 2006, November 30, 2005 and November 30, 2004 and the statements of operations, stockholders’ equity and cash flows for each of the years im the three-year period ended November 30, 2006 and the notes thereto."
  },
  {
    "id": "c016",
    "name": "“Holder”",
    "text": "“Holder” has the meaning given such term in the Policy."
  },
  {
    "id": "c017",
    "name": "“Incorporation Termination Date”",
    "text": "“Incorporation Termination Date” means January 31, 2008 or if, prior to such date, the Insurer receives a written notification from the Depositor that no Form 15D will be filed prior to such date with the SEC in respect of the Notes (a “No Form 15D Notice”), the first January 31 to occur thereafter."
  },
  {
    "id": "c018",
    "name": "“Indemnification Agreement”",
    "text": "“Indemnification Agreement” means the Indemnification Agreement, dated as of March 6, 2007, between the Insurer and the Underwriter."
  },
  {
    "id": "c019",
    "name": "“Indenture”",
    "text": "“Indenture” has the meaning given such term in the recitals."
  },
  {
    "id": "c020",
    "name": "“Indenture Trustee”",
    "text": "“Indenture Trustee” means Citibank, N.A., a national banking association, as indenture trustee under the Indenture, and any successor thereto under the Indenture."
  },
  {
    "id": "c021",
    "name": "“Insurance Agreement”",
    "text": "“Insurance Agreement” has the meaning given such term in the initial paragraph hereof."
  },
  {
    "id": "c022",
    "name": "“Insurer Financial Statements”",
    "text": "“Insurer Financial Statements” has the meaning assigned to such term in Section 2.03() below."
  },
  {
    "id": "c023",
    "name": "“Insured Notes”",
    "text": "“Insured Notes” means GreenPoint Mortgage Funding Trust 2007-HEI Mortgage- Backed Notes, Class A-1 and Class A-2 Notes."
  },
  {
    "id": "c024",
    "name": "“Insurer”",
    "text": "“Insurer” means XL Capital Assurance Inc., or any successor thereto, as issuer of the Policy."
  },
  {
    "id": "c025",
    "name": "“Tnsurer Information”",
    "text": "“Tnsurer Information” has the meaning given such term in Section 3.04(a)(v)."
  },
  {
    "id": "c026",
    "name": "“Investment Company Act”",
    "text": "“Investment Company Act” means the Investment Company Act of 1940, including, unless the context otherwise requires, the rules and regulations thereunder, as amended from time to time."
  },
  {
    "id": "c027",
    "name": "“Issuer”",
    "text": "“Issuer” has the meaning given such term in the recitals."
  },
  {
    "id": "c028",
    "name": "“Late Payment Rate”",
    "text": "“Late Payment Rate” means the lesser of (a) the greater of (i) the prime rate as published in the Wall Street Journal (or if no such rate is published thereby, in a publication selected by the Insurer) (any change in such rate of interest to be effective on the date such change is published) plus 2%, and (ii) the then applicable rate of interest on the Insured Notes and (b) the maximum rate permissible under applicable usury or similar laws limiting interest rates. The Late Payment Rate shall be computed on the basis of the actual number of days elapsed over a year of 360 days for any Payment Date."
  },
  {
    "id": "c029",
    "name": "“Material Adverse Change”",
    "text": "“Material Adverse Change” means, in respect of any Person, a material adverse change in the ability of such Person to perform its obligations under any of the Operative Documents, including any material adverse change in the business, financial condition, results of operations or properties of such Person on a consolidated basis with its subsidiaries which might have such effect."
  },
  {
    "id": "c030",
    "name": "“Moody’s”",
    "text": "“Moody’s” means Moody’s Investors Service, Inc., and any successor thereto."
  },
  {
    "id": "c031",
    "name": "“Notes”",
    "text": "“Notes” has the meaning given such term in the recitals."
  },
  {
    "id": "c032",
    "name": "“Offermg Document”",
    "text": "“Offermg Document” means the Prospectus, dated December 18, 2006, as supplemented by the Prospectus Supplement, dated March 5, 2007, as supplemented by the Free Writing Prospectus, dated March 2, 2007 in respect of the Notes and any amendment or supplement thereto, and any other offering document in respect of the Securities prepared by or on behalf of the Depositor that makes reference to the Policy."
  },
  {
    "id": "c033",
    "name": "“Operative Documents”",
    "text": "“Operative Documents” means this Insurance Agreement, the Indemnification Agreement, the Securities, the Certificate of Trust, the Sale and Servicing Agreement, the Servicing Agreement, the Custodial Agreement, the Purchase Agreement, the Depositor Purchase Agreement, the Assignment Agreement, the Trust Agreement, the Administration Agreement, the Indenture and each other document contemplated by any of the foregoing to which the Depositor, the Owner Trustee, the Master Servicer, the Servicer, the Indenture Trustee or the Trust is a party."
  },
  {
    "id": "c034",
    "name": "“Originators”",
    "text": "“Originators” means with respect to any Mortgage Loan, the entity that originated such Mortgage Loan before the Mortgage Loan was transferred to the Depositor."
  },
  {
    "id": "c035",
    "name": "“Owner Trustee”",
    "text": "“Owner Trustee” means Wilmington Trust Company, a banking corporation organized and existing under the laws of Delaware, not in its individual capacity but solely as owner trustee under the Trust Agreement, and any successor thereto under the Trust Agreement."
  },
  {
    "id": "c036",
    "name": "“Person”",
    "text": "“Person” means an individual, joint stock company, trust, unincorporated association, joint venture, corporation, business or owner trust, partnership, limited liability company or other organization or entity (whether governmental or private)."
  },
  {
    "id": "c037",
    "name": "“Policy”",
    "text": "“Policy” means the Financial Guaranty Insurance Policy No. CA03607A, together with all endorsements thereto, issued by the Insurer in favor of the Indenture Trustee, for the benefit of the Holders."
  },
  {
    "id": "c038",
    "name": "“Premium”",
    "text": "“Premium” means the premium payable in accordance with this Insurance Agreement, which shail be payable as “Premium Amounts” pursuant to the Premium Letter and payable in accordance with the Indenture."
  },
  {
    "id": "c039",
    "name": "“Premium Letter”",
    "text": "“Premium Letter” means the letter agreement among the Insurer, the Indenture Trustee, EMC and the Depositor dated the date hereof in respect of the Premium payable in consideration of the issuance of the Policy."
  },
  {
    "id": "c040",
    "name": "“Purchase Agreement”",
    "text": "“Purchase Agreement” has the meaning given such term in the recitals hereof."
  },
  {
    "id": "c041",
    "name": "“Registration Statement”",
    "text": "“Registration Statement” means the registration statement on Form S-3 (No. 333- 131374), including the prospectus, relating to the Notes, at the time it became effective."
  },
  {
    "id": "c042",
    "name": "“Regulation AB”",
    "text": "“Regulation AB” means Regulation AB pronmilgated under the Securities Act."
  },
  {
    "id": "c043",
    "name": "“S&P”",
    "text": "“S&P” means Standard & Poor’s Ratings Services, a division of The McGraw-Hill Companies, Inc., and any successor thereto."
  },
  {
    "id": "c044",
    "name": "“SEC”",
    "text": "“SEC” means the United States Securities and Exchange Commission."
  },
  {
    "id": "c045",
    "name": "“Securities”",
    "text": "“Securities” means the Notes and the Certificates."
  },
  {
    "id": "c046",
    "name": "“Securities Act”",
    "text": "“Securities Act” means the Securities Act of 1933, including, unless the context otherwise requires, the rules and regulations thereunder, as amended from time to time."
  },
  {
    "id": "c047",
    "name": "“Securities Exchange Act”",
    "text": "“Securities Exchange Act” means the Securities Exchange Act of 1934, including, unless the context otherwise requires, the rules and regulations thereunder, as amended from time to time."
  },
  {
    "id": "c048",
    "name": "“Servicer Information”",
    "text": "“Servicer Information” means the information contained under the heading “The Servicer” in the Offering Document."
  },
  {
    "id": "c049",
    "name": "“Sponsor”",
    "text": "“Sponsor” has the meaning given such term in the recitals to this Agreement."
  },
  {
    "id": "c050",
    "name": "“Transaction”",
    "text": "“Transaction” means the transactions contemplated by the Operative Documents, including the transactions described in the Offering Document."
  },
  {
    "id": "c051",
    "name": "“Trust”",
    "text": "“Trust” means GreenPoint Mortgage Funding Trust 2007-HE1 created pursuant to the Trust Agreement."
  },
  {
    "id": "c052",
    "name": "“Trust Agreement”",
    "text": "“Trust Agreement” has the meaning assigned to such item in the recitals hereof."
  },
  {
    "id": "c053",
    "name": "“Trust _Indenture Act”",
    "text": "“Trust _Indenture Act” means the Trust Indenture Act of 1939, including, unless the context otherwise requires, the rules and regulations thereunder, as amended from time to time."
  },
  {
    "id": "c054",
    "name": "“Underwriter”",
    "text": "“Underwriter” means Bear, Stearns & Co. Inc."
  },
  {
    "id": "c055",
    "name": "“Underwriting Agreement”",
    "text": "“Underwriting Agreement” means the Underwriting Agreement, dated as of April 13, 2006, as supplemented by the related Terms Agreement, dated as of March 2, 2007, between the Underwriter and the Depositor with respect to the offer and sale of the Notes, as such may be amended, modified or supplemented from time to time."
  },
  {
    "id": "c056",
    "name": "1.02. Agreement references",
    "text": "Section 1.02. Other Definitional Provisions. The words “hereof,” “herein” and “hereunder” and words of similar import when used in this Insurance Agreement shall refer to this Insurance Agreement as a whole and not to any particular provision of this Insurance Agreement, and Section, subsection, Schedule and Exhibit references are to this Insurance Agreement unless otherwise specified."
  },
  {
    "id": "c057",
    "name": "1.02. Singular and plural",
    "text": "The meanings given to terms defined herein shall be equally applicable to both the singular and plural forms of such terms."
  },
  {
    "id": "c058",
    "name": "1.02. Include and including",
    "text": "The words “inchide” and “including” shall be deemed to be followed by the phrase “without limitation.”"
  },
  {
    "id": "c059",
    "name": "2.01(a). Due Organization and Qualification—status",
    "text": "(a) Due Organization and Qualification. EMC is a corporation, duly organized, validly existing and in good standing under the laws of the State of Delaware, the Depositor is a limited liability company, duly organized, validly existing and in good standing under the laws of Delaware and the Issuer is a statutory trust duly organized, validly existing and in good standing under the laws of Delaware."
  },
  {
    "id": "c060",
    "name": "2.01(a). Due Organization and Qualification—approvals",
    "text": "Each of EMC, the Issuer and the Depositor is, or shall become, duly qualified to do business, is, or shall be, in good standing and has obtained, or shall obtain, all necessary licenses, permits, charters, registrations and approvals (together, “approvals”) necessary for the conduct of its business as currently conducted and as described in the Offering Document and the performance of its obligations under the Operative Documents to which it is a party in each jurisdiction in which the failure to be so qualified or to obtain such approvals would render any Operative Document unenforceable in any respect or would have a material adverse effect upon the Transaction."
  },
  {
    "id": "c061",
    "name": "2.01(b). Power and Authority",
    "text": "(b) | Power and Authority. Each of EMC, the Issuer and the Depositor has all necessary power and authority to conduct its business as currently conducted and as described in the Offering Document, to execute, deliver and perform its obligations under the Operative Documents to which it is a party and to consummate the Transaction."
  },
  {
    "id": "c062",
    "name": "2.01(c). Due Authorization",
    "text": "Due Authorization. The execution, delivery and performance of the Operative Documents by each of EMC, the Issuer and the Depositor has been duly authorized by all necessary action and does not require any additional approvals or consents, or other action by or any notice to or filing with any Person, including any governmental entity or any of the stockholders or beneficial owners, as applicable, of EMC, the Issuer or the Depositor, which have not previously been obtained or given by EMC, the Issuer or the Depositor."
  },
  {
    "id": "c063",
    "name": "2.01(d). Noncontravention",
    "text": "(d) | Noncontravention. The execution and delivery by each of EMC, the Issuer or the Depositor of the Operative Documents to which it is a party, the consummation of the Transaction and the satisfaction of the terms and conditions of the Operative Documents do not and will not: - (i) conflict with or result in any breach or violation of any provision of the applicable organizational documents of EMC, the Issuer or the Depositor or any law, rule, regulation, order, writ, judgment, injunction, decree, determination or award currently in effect having applicability to EMC, the Issuer or the Depositor or any of their respective material properties, including regulations issued by any administrative agency or other governmental authority having supervisory powers over EMC, the Issuer or the Depositor, which conflict, breach or violation reasonably could be expected to result in a Material Adverse Change; (ii) constitute a default by EMC, the Issuer or the Depositor under, result in the acceleration of any obligation under, or breach any provision of any loan agreement, mortgage, indenture or other agreement or instrument to which EMC, the Issuer or the Depositor is a patty or by which any of their respective properties is or may be bound or affected, which default, acceleration or breach reasonably could result in a Material Adverse Change; or (iii) result in or require the creation of any lien upon or in respect of any assets of EMC, the Issuer or the Depositor, which lien could reasonably be expected to result in a Material Adverse Change."
  },
  {
    "id": "c064",
    "name": "2.01(e). Legal Proceedings",
    "text": "(ec) Legal Proceedings. There is no action, proceeding or investigation by or before any court, governmental or administrative agency or arbitrator against or affecting EMC, the Issuer or the Depositor or any of their respective subsidiaries, any properties or rights of EMC, the Issuer or the Depositor or any of their respective subsidiaries or any of the HELOCs pending or, to EMC’s, the Issuer’s or the Depositor’s knowledge after reasonable inquiry, threatened, which, in any case, if decided adversely to EMC, the Issuer or the Depositor or any such subsidiary could result in a Material Adverse Change with respect to EMC, the Issuer or the Depositor."
  },
  {
    "id": "c065",
    "name": "2.01(f). No Default—contractual obligations",
    "text": "69) No Default. Neither EMC nor the Depositor is in default under or with respect to any of its contractual obligations in any respect which could have a material adverse effect on the rights, interests or remedies of the Insurer hereunder or under the other Operative. Documents or on its ability to perform its obligations hereunder or under the other Operative Documents to which it is a party."
  },
  {
    "id": "c066",
    "name": "2.01(f). No Default—Default or Event",
    "text": "No Default or Event of Default has occurred and is continuing."
  },
  {
    "id": "c067",
    "name": "2.01(g). Valid and Binding Obligations—Operative Documents",
    "text": "(g) Valid and Binding Obligations. The Operative Documents (other than the Securities), when executed and delivered by EMC, the Issuer or the Depositor, will constitute the legal, valid and binding obligations of each of EMC, the Issuer and the Depositor, enforceable in accordance with their respective terms, except as such enforceability may be limited by bankruptcy, insolvency, reorganization, moratorium or other similar laws affecting creditors’ rights generally and general equitable principles and public policy considerations as to rights of indemnification for violations of federal securities laws."
  },
  {
    "id": "c068",
    "name": "2.01(g). Valid and Binding Obligations—Securities",
    "text": "the Certificates when executed, authenticated and delivered in accordance with the Trust Agreement, will be validly issued and outstanding and entitled to the benefits of the Trust Agreement."
  },
  {
    "id": "c069",
    "name": "2.01(g). Valid and Binding Obligations—no denial",
    "text": "Each of EMC, the Issuer and the Depositor will not at any time in the future deny that the Operative Documents to which it is a party constitute the legal, valid and binding obligations of EMC, the Issuer and the Depositor, as applicable."
  },
  {
    "id": "c070",
    "name": "2.01(h). Financial Statements—accuracy",
    "text": "(h) Financial Statements. The Financial Statements of EMC, copies of which have been furnished to the Insurer, (i) are, as of the dates and for the periods referred to therein, complete and correct in all material respects, (ii) present fairly the financial condition and results of operations of EMC as of the dates and for the periods indicated and (iii) have been prepared in accordance with generally accepted accounting principles consistently applied, except as noted therein (subject as to interim statements to normal year-end adjustments)."
  },
  {
    "id": "c071",
    "name": "2.01(h). Financial Statements—no Material Adverse Change",
    "text": "Since the date of the most recent Financial Statements, there has been no Material Adverse Change in respect of EMC, the Issuer or the Depositor."
  },
  {
    "id": "c072",
    "name": "2.01(h). Financial Statements—contingent liabilities",
    "text": "Except as disclosed in the Financial Statements, none of EMC, the Issuer or the Depositor is subject to any contingent liabilities or commitments that, individually or in the aggregate, have a material possibility of causing a Material Adverse Change in respect of EMC, the Issuer or the Depositor."
  },
  {
    "id": "c073",
    "name": "2.01(i). Compliance with Law",
    "text": "Q) Compliance with Law, etc. No practice, procedure or policy employed or proposed to be employed by EMC, the Depositor or the Issuer in the conduct of its business violates any law, regulation, judgment, agreement, order or decree applicable to it which, if enforced, could reasonably be expected to result in a Material Adverse Change with respect to it or have a material adverse effect on the Transaction."
  },
  {
    "id": "c074",
    "name": "2.01(j). Good Title; Absence of Liens",
    "text": "(j) Good Title; Absence of Liens or Security Interest. The Issuer is the owner of, and has good and marketable title to, all of the Collateral free and clear of all liens and has full right, power and lawful authority to assign, transfer and pledge the Collateral (and any documents which are a part thereof) and all such substitutions therefor and additions thereto delivered under the Indenture."
  },
  {
    "id": "c075",
    "name": "2.01(k). Taxes—returns and payments",
    "text": "(k) Taxes. Each of EMC, the Issuer and the Depositor has filed (or caused to be filed) prior to the date hereof all federal and state tax returns that are required to be filed and has paid all taxes, including any assessments received by it that are not being contested in good faith, to the extent that such taxes have become due, except with respect to any failures to file or pay that, individually or in the aggregate, would not result in a Material Adverse Change with respect to EMC, the Issuer or the Depositor."
  },
  {
    "id": "c076",
    "name": "2.01(k). Taxes—Transaction charges",
    "text": "Any taxes, fees and other governmental charges _ payable by EMC, the Issuer or the Depositor in connection with the Transaction, the execution and delivery of the Operative Documents and the issuance of the Securities have been paid or shall have been paid at or prior to the Closing Date if such taxes, fees or other governmental charges were due on or prior to the Closing Date."
  },
  {
    "id": "c077",
    "name": "2.01(l). Accuracy of Information—Documents",
    "text": "(1) Accuracy of Information. Neither the Operative Documents nor other material information relating to the HELOCs, the operations of EMC, the Issuer or the Depositor or the financial condition of EMC, the Issuer or the Depositor (collectively, the “Documents”), as amended, supplemented or superseded, furnished to the Insurer in writing or in electronic CONFIDENTIAL . SYN-EMC00062225 Fem HAS oe CONFIDENTIAL form by EMC, the Issuer or the Depositor contains any statement of a material fact which was untrue or misleading in any material respect when made."
  },
  {
    "id": "c078",
    "name": "2.01(l). Accuracy of Information—circumstances",
    "text": "Each of EMC, the Issuer and the Depositor has no knowledge of any circumstances that could reasonably be expected to cause a Material Adverse Change with respect to EMC, the Issuer or the Depositor."
  },
  {
    "id": "c079",
    "name": "2.01(l). Accuracy of Information—subsequent developments",
    "text": "Since the furnishing of the Documents, there has been no change nor any development or event involving a prospective change known to EMC, the Issuer or the Depositor that would render any of the Documents untrue or misleading in any material respect."
  },
  {
    "id": "c080",
    "name": "2.01(l). Accuracy of Information—Data Tape",
    "text": "Without limiting the generality of the foregoing, the information in the Data Tape with respect to each HELOC is true and correct as of the Cut-off Date."
  },
  {
    "id": "c081",
    "name": "2.01(m). Compliance With Securities Laws—offer and sale",
    "text": "(m) Compliance With Securities Laws. Each of the offer of the Notes and the sale or placement of the Class B-2 Notes complies or shall comply in all material respects with all requirements of law, including all registration and reporting requirements of applicable securities laws."
  },
  {
    "id": "c082",
    "name": "2.01(m). Compliance With Securities Laws—Offering Document",
    "text": "Without limiting the foregoing, the Offering Document does not contain any untrue statement of a material fact and does not omit to state a material fact necessary to make the statements made therein, in light of the circumstances under which they were made, not misleading; provided, however, that no representation is made with respect to the information in the Offering Document regarding the Insurer set forth under the captions “The Policy” and “The Insurer” or the financial statements of the Insurer as included in the Free Writing Prospectus and as incorporated by reference into the Prospectus Supplement, the Servicer Information or the Underwriter Information."
  },
  {
    "id": "c083",
    "name": "2.01(m). Compliance With Securities Laws—Offered Notes",
    "text": "The offer of the Offered Notes and the Class B-2 Notes has not been and will not be in violation of the Securities Act or any other federal or state securities laws."
  },
  {
    "id": "c084",
    "name": "2.01(m). Compliance With Securities Laws—Indenture",
    "text": "The Indenture has been qualified under the Trust Indenture Act."
  },
  {
    "id": "c085",
    "name": "2.01(m). Compliance With Securities Laws—Trust",
    "text": "Based upon advice of legal counsel, the Trust Agreement is not required to be qualified under the Trust Indenture Act and each of the Issuer and the Trust Estate is not required to be registered as an “investment company” under the Investment Company Act."
  },
  {
    "id": "c086",
    "name": "2.01(n). Operative Documents—representations",
    "text": "(n) Operative Documents. Each of the representations and warranties of EMC, the Issuer and the Depositor contained in the applicable Operative Documents is true and correct in all material respects and each of EMC, the Issuer and the Depositor hereby makes each such representation and warranty to, and for the benefit of, the Insurer as if the same were set forth in full herein."
  },
  {
    "id": "c087",
    "name": "2.01(n). Operative Documents—no denial",
    "text": "Each of EMC, the Issuer and the Depositor will not at any time in the future deny that the Operative Documents to which it is a party constitute the legal, valid and binding obligations of EMC, the Issuer and the Depositor, as applicable."
  },
  {
    "id": "c088",
    "name": "2.01(o). Solvency; Fraudulent Conveyance—solvency",
